-- Saved Dashboard Agent layouts.
--
-- Stores ONLY the dashboard component's props.widgets array -- the placed
-- layout. props.availableWidgets (the catalog the agent chooses from) is
-- generated by scripts/gen_dashboard_widgets.py and lives in view.json; it is
-- deliberately not persisted here, so a catalog change reaches every saved
-- dashboard instead of being frozen into each row.
--
-- is_demo is the only thing keeping a row alive past midnight: the
-- DashboardConfigPurge gateway timer deletes every row where is_demo is false
-- and updated_at is older than today, so the demo environment stays clean
-- without anyone tidying up after a show.
--
-- Replayed on every `docker compose up` by the postgres-init service, so
-- everything here must be safe to re-run.

CREATE TABLE IF NOT EXISTS ex_icc_dashboard_config (
	id			SERIAL NOT NULL,
	name		TEXT NOT NULL,
	widgets_json	JSONB NOT NULL,
	is_demo		BOOLEAN NOT NULL DEFAULT FALSE,
	created_at	TIMESTAMPTZ NOT NULL DEFAULT now(),
	updated_at	TIMESTAMPTZ NOT NULL DEFAULT now(),
	CONSTRAINT ex_icc_dashboard_config_pkey PRIMARY KEY (id)
);

-- Name is the handle the operator types in the Save popup, so it has to be
-- unique: saving under an existing name is an update, not a second row.
CREATE UNIQUE INDEX IF NOT EXISTS ex_icc_dashboard_config_name_key
	ON ex_icc_dashboard_config (lower(name));

-- The purge sweeps on these two together.
CREATE INDEX IF NOT EXISTS ex_icc_dashboard_config_purge_idx
	ON ex_icc_dashboard_config (is_demo, updated_at);
